<?php
 if ( ! defined( 'ABSPATH' ) ) { exit; } use Elementor\Controls_Manager; require_once __DIR__ . '/class-nexvio-product-grid-widget.php'; class Nexvio_Products_Grid_Widget extends Nexvio_Product_Grid_Widget { public function get_name() { return 'nexvio_products_grid'; } public function get_title() { return esc_html__( 'Products Card Layouts', 'nexvio' ); } protected function gallery_ui() { return ''; } public function get_icon() { return 'eicon-products'; } public function get_keywords() { return array( 'nexvio', 'woocommerce', 'products', 'grid', 'featured', 'sale', 'best sellers', 'layout' ); } protected function register_controls() { $this->register_design_section(); $this->register_query_section(); $this->register_card_sections(); $this->register_grid_layout_section(); $this->register_pagination_section(); $this->register_gs_card_styles(); $this->register_pagination_style_section(); $this->register_empty_style_section(); $this->limit_classic_controls(); $this->update_control( 'limit', array( 'label' => esc_html__( 'Products per page', 'nexvio' ), 'description' => esc_html__( 'With pagination on, the next products are on the following pages.', 'nexvio' ), ) ); } protected function grid_settings( $s ) { $s['source_mode'] = 'custom'; $s['loop_hooks'] = ''; $s['show_count'] = ''; $s['show_sorting'] = ''; $s['preview_limit'] = isset( $s['limit'] ) ? (int) $s['limit'] : 12; return $s; } protected function extra_root_classes() { return array( 'nexvio-pg--grid' ); } protected function page_param() { return 'nexvio-pg-' . sanitize_key( $this->get_id() ); } } 